import sqlite3, re, csv, collections
con=sqlite3.connect('file:drive-index/drive.sqlite?mode=ro',uri=True)
ROOT='00_Primary_Storage_Drive/03_REPORTS'; A=ROOT+'/GPS REPORTS'
