FOLD={'GPS REPORTS':'GPS_REPORTS','FB_FA23_GPS':'Football_FA2023_GPS','FB_FA24_GPS':'Football_FA2024_GPS','FB_FA23_JSON':'Football_FA2023_JSON'}
def clean(s):
    s=re.sub(r'\s*\(\d+\)$','',s); s=re.sub(r'\s*-\s+|\s+-\s*',' ',s)
    s=re.sub(r'\s+','_',s.strip()); return re.sub(r'_+','_',s).strip('_')
out=[]
for fid,name,folder,mime in rows:
    if 'folder' in mime:
        if name in FOLD: out.append((folder,name,FOLD[name])); 
        continue
    rel=folder[len(A):].strip('/').split('/') if folder!=A else []
    stem,ext=name.rsplit('.',1)
    s=clean(stem)
    if rel[:1]==['FB_FA24_GPS']:
        new='Football_FA2024_'+re.sub(r'^FA24_','',s)
    elif len(rel)>=2 and rel[1]=='FB_FA23_JSON':
        new='Football_FA2023_'+s
    elif len(rel)==3 and rel[1].startswith('WK'):
        wk,sess=rel[1],rel[2]; opp=wk.split('_',1)[1]
        s=re.sub(r'^FA23_','',s); s=re.sub(rf'^{opp}_*{sess}_','',s)
        new=f'Football_FA2023_{wk}_{sess}_{s}'
    elif rel==['FB_FA23_GPS','COMBINED']:
        new='Football_FA2023_'+re.sub(r'^FA23_','',s)
    elif rel==['FB_FA23_GPS']:
        new='Football_FA2023_'+re.sub(r'^2023_','',s)
    else:
        new='??'+s
    out.append((folder,name,new+'.'+ext))
# checks
clash=collections.Counter((f,n) for f,_,n in out)
print('rows',len(out),'unchanged',sum(o==n for _,o,n in out),'clashes',[k for k,v in clash.items() if v>1][:5])
dbl=[n for _,_,n in out if re.search(r'(?:^|_)([A-Z]+_[PG]\d+)_.*\1',n) or '??' in n or re.search(r'FA23|FB_',n)]
print('doubled/odd:',dbl[:10])
out.sort(key=lambda r:(r[0].count('/'),r[0],r[1]))
with open('drive-index/rename_2026-10-31_gps_all.csv','w',newline='') as f:
    w=csv.writer(f); w.writerow(['folder','old','new']); w.writerows([o for o in out if o[1]!=o[2]])
import random; random.seed(3)
for f,o,n in [out[0],out[1],out[2],out[3]]+random.sample(out,14): print(f'{o!r:45} -> {n}')
